  "vision.intro.lead": "In 2018 had ik een <span class=\"wf-hl\">visie</span> over hoe ik <span class=\"wf-hl\">elke hond op aarde kon redden</span>. En het is eigenlijk simpel — elke hondenliefhebber <span class=\"wf-hl\">verenigt zich in één gemeenschap</span>, één die een hond ziet als <span class=\"wf-hl\">meer dan alleen een dier</span>. En hier zijn we dan…",
