  "heroglyph.flow.dogCharacter.slide.guardian.desc": "Bewaakt de deur alsof het de poort naar het hiernamaals is. Blaft eerst, vragen stelt hij nooit.",
  "heroglyph.flow.dogCharacter.slide.player.desc": "Verkoopt zijn ziel voor nog één worp met de bal. Grootste geluk: zijn lievelingsspeeltje.",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "Geen uitknop. Geen batterijen nodig. Meest gestelde vraag: waar zit die hond op?",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "Moderne piraat met een eigen wereld en eigen regels. Selectief gehoor is zijn eerste wet.",
  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "Er bestaan twee soorten honden — en de ene zie je zo aan voor een vis. Natte vacht: 100% geluk.",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "Eten is de missie. Volle inzet, nul aarzeling — en hij eet ook op wat jij laat staan.",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "Vreemden bestaan niet voor hem. Begroet de postbode als een lang verloren zielsverwant. Elke keer weer.",
