  "notFound.code": "404",
  "notFound.message": "Oeps! Pagina niet gevonden",
  "notFound.returnHome": "Terug naar Home",
  "about.origin.title": "De<br />Oorsprong",
  "about.origin.sub": "Schuif en lees",
  "about.origin.skip": "of overslaan",
  "about.crawl.intro": "Tien jaar geleden, in een asiel in het hart van Europa….",
  "about.crawl.episode": "Aflevering I",
  "about.crawl.faith": "Een Nieuw Geloof",
  "about.crawl.p1": "In 2016 kwamen acht zwarte puppy's aan in het asiel, weggegooid in een enkele doos. Zeven vonden een thuis. De grootste wilde niemand — hij wachtte een heel jaar. Zijn naam was Hekthor.",
  "about.crawl.p2": "Op een dag kwam een stel naar het asiel om Sindy te bekijken, een klein wit teefje dat ze wilden adopteren. Puur bij toeval was Hekthor op dat moment in haar hok — zijn eigen hok werd net schoongemaakt. De man, die alleen meeging voor de rit en nooit een hond wilde, werd verliefd op de zwarte hond die hij voor het allereerst zag.",
  "about.crawl.p3": "Een week later waren ze samen, en een mooi verhaal begon. Het hele leven van de man veranderde, en na verloop van tijd begreep hij één ding: alleen iemand die een hond heeft en weet hoe de liefde van een hond voelt, kan honden in nood echt helpen.",
  "about.crawl.p4": "En zo werd de Heroglyph geboren — een symbool bedoeld om hondenliefhebbers overal ter wereld te verenigen in de grootste gemeenschap die de wereld ooit heeft gekend. Een gemeenschap die zal opkomen voor ons, voor onze honden en voor de generaties die komen — voor mensen die niet bang zijn toe te geven dat een hond niet zomaar een dier is, maar een wezen dat ons betere mensen maakt.",
  "about.crawl.p5": "Nu begint de reis naar het eerste mijlpaal — het creëren van 1.000.000 Heroglyphs. En jij kunt er deel van uitmaken. Want de enigen die gek genoeg zijn om te geloven dat ze de wereld kunnen veranderen, zijn degenen die het ook echt doen.",
  "about.crawl.p6": "Wij geloven in de hond.",
  "about.timeline.heading": "Het Verhaal van Dogypt",
  "about.milestone.1.year": "2017",
  "about.milestone.1.tag": "Het Asiel",
  "about.milestone.1.title": "Schat in het Asiel",
  "about.milestone.1.body": "Een zwarte hond die niemand wilde, wachtte achter een asielshek. Zijn naam werd Hekthor. Hem adopteren was geen redding — het was het begin van alles.",
  "about.milestone.2.year": "2018",
  "about.milestone.2.tag": "De Band",
  "about.milestone.2.title": "Een Eeuwige Band",
  "about.milestone.2.body": "Hij loodste me door de zwaarste periode van mijn leven zonder één woord te zeggen. Elke hondenliefhebber kent dit — ze dragen je precies op het moment dat je valt.",
  "about.milestone.3.year": "2019",
  "about.milestone.3.tag": "De Reis",
  "about.milestone.3.title": "De Wandeling Die een Boek Werd",
  "about.milestone.3.body": "Samen wandelden we door Slowakije — 42 dagen, 800 kilometer, één stille belofte. Die weg werd een boek: „Cesta s Hrdinom\" — De Weg met een Held.",
  "about.milestone.4.year": "2022",
  "about.milestone.4.tag": "De Naam",
  "about.milestone.4.title": "Een Natie van Hondenliefhebbers",
  "about.milestone.4.body": "Piramides, mystiek, de eeuwige glorie van Egypte — de mensheid is er al millennia door betoverd. Verbind dat aan de oneindige liefde van een hond en je krijgt DOGYPT. Ik bezegelde het idee op Expo Dubai 2022, verkleed als farao.",
  "about.milestone.5.year": "Nu",
  "about.milestone.5.tag": "Dogypt",
  "about.milestone.5.title": "De Reis Begint Met Jou",
  "about.milestone.5.body": "DOGYPT is een beweging voor iedereen wiens leven werd veranderd door een hond. Gebouwd op de oudste, meest eerlijke band op aarde. Hekthor is stichter #1. Jij bent de volgende.",
  "about.outro.quoteLead": "Het Was Nooit",
  "about.outro.quoteTail": "\"Gewoon een Hond.\"",
  "about.outro.body": "Je kent het gevoel al — dat een hond niet iets is dat je bezit, maar <strong>iemand van wie je houdt</strong>. Stel je nu voor dat die liefde georganiseerd, verbonden en <strong>krachtig genoeg is om dingen te veranderen.</strong> En dat is waarom <strong>DOGYPT</strong> bestaat.",
  "about.outro.name1": "Matej",
  "about.outro.and": "en",
  "about.outro.name2": "Hekthor",
  "about.outro.cta": "Word Dogyptiër",
  "about.reel.prev": "Vorige foto",
  "about.reel.next": "Volgende foto",
  "religion.hook.number": "1,2",
  "religion.hook.billion": "MILJARD",
  "religion.hook.people": "MENSEN",
  "religion.hook.note": "(15% wereldwijd)",
  "religion.hook.bow": "buigen voor de koe",
  "religion.hook.doglovers": "HONDENLIEFHEBBERS?",
  "religion.hook.worship": "LATEN WE ONZE HONDEN AANBIDDEN.",
  "religion.cta": "Word Dogyptiër",
  "religion.aria.question": "De Vraag",
  "religion.aria.preamble": "Preambule",
  "religion.aria.sacredIndex": "Heilige Index",
  "religion.aria.scrollDown": "Scroll naar beneden",
  "religion.preamble.headlineGrad": "In Hond",
  "religion.preamble.headlineLine": "Wij Vertrouwen",
  "religion.preamble.text": "Wij, de natie van hondenliefhebbers — wetende van de <strong>oneindige trouw</strong>, de <strong>ware liefde</strong> en de <strong>zuivere ziel</strong> van elke hond op aarde — teneinde de positie van honden in de menselijke samenleving te verheffen, hen een <strong>gemeenschap</strong> te bouwen, hun leven te <strong>verbeteren</strong> en het lot van elke hond in nood te <strong>herschrijven</strong>, geven wij onszelf deze grondwet.",
  "religion.preamble.oath": "De Eed van de Roedel",
  "religion.bookTitle": "De \"Bijbel\" voor hondenliefhebbers",
  "religion.book.sealAlt": "Het Dogyptiërzegel",
  "religion.book.titleThe": "De",
  "religion.book.titleBrand": "Dogypt",
  "religion.book.titleConstitution": "Grondwet",
  "religion.book.trust": "In Hond We Vertrouwen",
  "religion.book.sub": "Verplichte lectuur voor elke hondenliefhebber die Dogyptiër wil worden.",
  "religion.book.cta1.kicker": "Het Pad Begint",
  "religion.book.cta1.head": "Sluit je aan bij<br />de Religie",
  "religion.book.cta1.text": "Schrijf je in voor de hondenreligie — neem een Heroglyph.",
  "religion.book.cta1.btn": "Word Dogyptiër",
  "religion.book.cta2.kicker": "Het Volledige Woord",
  "religion.book.cta2.head": "Lees de<br />Grondwet",
  "religion.book.cta2.text": "Elk canon, credo en gebod — volledig.",
  "religion.book.cta2.btn": "Volledige Grondwet",
  "religion.book.coverOpenAria": "Open de Grondwet",
  "religion.book.coverAlt": "De Dogyptiër Grondwet",
  "religion.book.hint": "Tik op het boek om te openen",
  "religion.book.close": "Boek sluiten",
  "religion.book.prevPage": "Vorige pagina",
  "religion.book.nextPage": "Volgende pagina",
  "nav.wall": "Muur",
  "nav.vision": "Visie",
  "nav.religion": "Religie",
  "nav.about": "Over ons",
  "nav.login": "INLOGGEN",
  "wall.hero.taglineLead": "De plek waar",
  "wall.hero.taglineGod": "HOND IS GOD.",
  "wall.hero.cta": "Word Dogyptiër",
  "wall.hero.total": "1.000.000",
  "wall.hero.dogs": "HONDEN",
  "wall.hektor.msg": "Hekthor, jij bent mijn grootste held, mijn beste vriend, mijn trouwe metgezel, mijn meedogenloze mentor — jij bent het mooiste verhaal van mijn leven. Dankzij jou heb ik een hondenreligie gesticht en besefte ik dat mijn liefde niets bijzonders is — iedereen die ooit van een hond heeft gehouden, voelt in zijn hart precies hetzelfde. Dank je voor ons mooiste leven samen. Ik hou van je.",
  "wall.info.title": "1.000.000 honden.<br/>Gaan we het halen?",
  "wall.info.body": "DOGYPT is een beweging voor hondenliefhebbers. Elke hond krijgt een unieke Heroglyph — hun vaste plek in de wereldwijde roedel. We verzamelen één miljoen helden. Wees een van de eersten.",
