  "payment.yourDog": "jouw hond",
  "payment.sealing": "FOTO WORDT VERZEGELD...",
  "payment.preparing": "VOORBEREIDEN...",
  "payment.pay": "BETALEN MET STRIPE",
  "payment.secured": "Beveiligd door Stripe · Kaart, Apple Pay, Google Pay",
  "payment.error": "De betaling kon niet starten. Controleer je verbinding en probeer het opnieuw.",
  "payment.photoNotReady": "De foto van je hond is nog niet helemaal geüpload. Ga terug naar de fotostap en voeg hem opnieuw toe.",
