  "heroglyph.sales.transparency.footer": "Elke euro blijft in de openbaarheid, voor elk lid om te zien. Je betaalt geen bedrijf — je voedt de roedel.",
  "entry.declare.eyebrow": "Hierbij verklaar ik",
  "entry.title": "In Hond Vertrouw Ik",
  "entry.subtitle": "Dit is geen grap. Elke serieuze religie moet deze dingen verklaren.",
  "entry.criteria.theology.title": "Theologie",
  "entry.criteria.theology.body": "Beste vriend, beschermer, leraar, partner in elk avontuur. De hond geeft liefde zonder voorwaarden — en aan zijn zijde lopen maakt ons menselijker.",
  "entry.criteria.canon.title": "Canon",
  "entry.criteria.canon.body": "Elk geloof heeft zijn schrift. Het onze is DOGMA: onze band met de hond, opgetekend in twaalf hoofdstukken, gratis te lezen op dogma.dogypt.com.",
  "entry.criteria.community.title": "Gemeenschap",
  "entry.criteria.community.body": "Wij zijn hondenliefhebbers met een doel. Alleen kan ieder van ons weinig veranderen — samen kent onze kracht geen grens.",
  "entry.criteria.symbol.title": "Symbool",
  "entry.criteria.symbol.body": "Elk geloof heeft zijn teken. Het onze is de Heroglyph: een uniek heilig merk voor elke hond, verstaan in elke taal, overal.",
  "entry.criteria.ritual.title": "Ritueel",
  "entry.criteria.ritual.body": "De wandeling. Dagelijkse therapie die lichaam en geest in vorm houdt — en de ziel ook. Het oudste ritueel dat we al volgen zonder dat iemand het ons opdraagt.",
  "entry.criteria.vision.title": "Visie",
  "entry.criteria.vision.body": "De band tussen mens en hond verheffen — en strijden voor het respect en het betere leven dat elke hond toekomt.",
