  "entry.criteria.offerings.note": "(een symbolisch eerbetoon)",
  "entry.criteria.offerings.pill": "€11 · eenmalig",
  "entry.criteria.offerings.tag": "100% transparantie",
  "entry.criteria.offerings.body": "€11, eenmalig. Een symbolische offergave — elke inkomst en elke uitgave in een grootboek dat voor iedereen open ligt. De energie die ons in leven houdt.",
  "entry.criteria.legitimacy.title": "Legitimiteit",
  "entry.criteria.legitimacy.pill": "nog {count} leden",
  "entry.criteria.legitimacy.body": "Duizend oprichters, en we zijn sterk genoeg om ons te registreren als een natie die de wet moet erkennen. De laatste mijlpaal — alleen jij kunt die bereiken.",
