  "heroglyph.flow.more.ainubis.d": "Onze gepersonaliseerde AI, je hulp en mentor. Hij kent je hond door en door. Leer van zijn bronnen, kijk erin en voeg je eigen materiaal en ervaring toe.",
  "heroglyph.flow.more.ainubis.t": "AINUBIS",
  "heroglyph.flow.more.cause.d": "DOGYPT maakt het leven van hondenliefhebbers makkelijker, maar brengt ook goede mensen samen en helpt honden in nood — volledig transparant. Zelfs de oprichter van DOGYPT, HEKTHOR, komt uit een asiel.",
  "heroglyph.flow.more.cause.t": "HOGER DOEL",
  "heroglyph.flow.more.close": "Sluiten",
  "heroglyph.flow.more.dogid.d": "Het complete profiel van je hond op één plek. Wat je invult, gebruikt onze AINUBIS. Een handig ‘rapport’, altijd bij de hand, bijvoorbeeld bij de dierenarts.",
  "heroglyph.flow.more.dogid.t": "DOG ID",
  "heroglyph.flow.more.dogtrip.d": "Hondvriendelijke avonturen van over de hele wereld op één plek. Voeg je favoriete uitje toe en deel het met de roedel. Laat je inspireren door anderen, verzamel punten, badges en levels.",
  "heroglyph.flow.more.dogtrip.t": "DOGTRIP",
  "heroglyph.flow.more.eyebrow": "DOGYPT-lidmaatschap",
  "heroglyph.flow.more.glyph.d": "Een uniek symbool dat je hond perfect vangt. Een universele taal die hondenliefhebbers moet verenigen. Jouw sleutel tot DOGYPT.",
  "heroglyph.flow.more.glyph.t": "HEROGLYPH",
  "heroglyph.flow.more.money.d": "Van elke €11 gaat €5 naar ontwikkeling, €3 naar de gemeenschap, €2 naar het redden van honden en €1 naar Hekthors voerbak. Elke uitgave wordt vastgelegd en openbaar gemaakt.",
  "heroglyph.flow.more.money.t": "WAAR HET GELD HEENGAAT",
  "heroglyph.flow.more.next": "Volgende",
  "heroglyph.flow.more.pack.d": "Toegang tot een platform gebouwd voor hondenliefhebbers. De app blijft groeien en zal hondenliefhebbers op alle vlakken van dienst zijn.",
  "heroglyph.flow.more.pack.t": "LEDENOMGEVING",
  "heroglyph.flow.more.prev": "Vorige",
  "heroglyph.flow.more.sniffer.d": "Vind een maatje, een stel of een groep voor uitjes, vaste wandelingen of een roadtrip-avontuur. Een datingapp speciaal voor honden en hun mensen.",
  "heroglyph.flow.more.sniffer.t": "SNIFFER",
