  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. Binnen de roedel: wat andere leden zien",
  "privacy.s12.body": "Artikel 3 beschrijft het openbare GodsGrid. Binnen de roedel — in het ledengebied — zien andere ingelogde leden meer: je voornaam, je Dogyptiër-nummer, de naam en foto van je hond, de kenmerken die je over je hond hebt ingevuld, de tochten die je hebt vastgelegd of aangekondigd, je beoordelingen en reacties, en wat je ook op je profiel hebt geschreven. Ze zien niet je e-mailadres, je postadres, je betaalgegevens of je berichten met anderen. Wanneer je een tocht als open aankondigt, worden de route, de datum en je hond zichtbaar voor elk lid, zodat het kan vragen om mee te doen — dat is wat aankondigen betekent. Een tocht die je privé houdt, zien alleen jij en de mensen die al meegaan. Jij kiest welke van de twee het is, en je kunt dat op elk moment wijzigen.",
  "privacy.s13.title": "13. Berichten & meldingen",
  "privacy.s13.body": "Privéberichten tussen leden worden opgeslagen in onze database (Supabase), zodat gesprekken tussen sessies bewaard blijven. Rechtsgrondslag: art. 6 lid 1 sub b AVG — ze zijn onderdeel van het lidmaatschap dat je hebt betaald. We lezen ze niet routinematig en gebruiken ze nooit voor reclame of profilering. We openen een gesprek alleen wanneer het wordt gemeld, wanneer we een specifiek misbruik- of beveiligingsincident onderzoeken, of wanneer de wet dat vereist. Een melding slaat de reden die je hebt gekozen op, je optionele notitie en een verwijzing naar wat je hebt gemeld — niet een afzonderlijke kopie ervan. Blokkeren wordt opgeslagen als een paar lid-identificatoren. Als je je account verwijdert, verdwijnen je berichten mee; de kopie in de thread van de andere persoon blijft staan, weergegeven als afkomstig van een verwijderd lid, omdat dat gesprek ook van hen is.",
  "terms.s12.title": "12. Inhoud die je plaatst",
  "terms.s12.body": "Naast je HEROGLYPH kun je binnen de roedel inhoud plaatsen: foto's van tochten, routes en locaties, beschrijvingen van tochten, beoordelingen, reacties en vragen, en wat je ook op je profiel schrijft. Wanneer je een tocht markeert als gelopen, zien andere leden je voornaam en de honden die hem met jou hebben gelopen. Je blijft eigenaar van alles wat je plaatst. Door het te plaatsen geef je DOGYPT s.r.o. een wereldwijde, royaltyvrije, niet-exclusieve licentie om die inhoud op te slaan, weer te geven en aan te passen met het doel de Dienst te laten draaien en te promoten — bijvoorbeeld door je foto van de tocht op de kaart, in een tochtenlijst of op een deelkaart te tonen. De licentie geldt zolang de inhoud in de Dienst staat; verwijder je de inhoud of je account, dan vervalt ze, behalve voor backups, die op hun normale cyclus verlopen. We verkopen je inhoud niet en licentiëren ze aan niemand anders voor eigen gebruik. Plaats alleen waarvoor je het recht hebt — ook foto's die iemand anders heeft gemaakt en mensen die daarop herkenbaar zijn.",
  "terms.s13.title": "13. Berichten tussen leden",
  "terms.s13.body": "Leden kunnen elkaar rechtstreeks schrijven. Berichten zijn privé tussen de deelnemers — we lezen ze niet routinematig en gebruiken ze nooit voor reclame. Ze worden op onze servers opgeslagen zodat het gesprek er nog is wanneer je terugkomt, en we kunnen een gesprek in drie gevallen lezen: wanneer iemand het meldt, wanneer we een specifiek misbruik- of beveiligingsincident onderzoeken, of wanneer de wet dat vereist. Je kunt een ander lid op elk moment blokkeren; blokkeren werkt onmiddellijk en in beide richtingen. Behandel berichten zoals elk ander online gesprek — stuur geen betaalgegevens, wachtwoorden of documenten die je niet opgeslagen wilt zien.",
  "terms.s14.title": "14. Melden & moderatie",
  "terms.s14.body": "Profielen, tochten en gesprekken kunnen worden gemeld. Een melding komt bij ons terecht en wordt door een mens gelezen — vandaag is dat de oprichter, Matej Stacho. We streven ernaar elke melding binnen 7 dagen te bekijken. Afhankelijk van wat we vinden, doen we misschien niets, verwijderen we de inhoud, waarschuwen we het lid, beperken we wat het mag plaatsen, of sluiten we het account. Als we actie ondernemen tegen je inhoud, laten we je de reden per e-mail weten, en je kunt reageren en het betwisten. We kunnen inhoud ook op eigen initiatief verwijderen wanneer die Artikel 7 overtreedt. Opzettelijk of herhaald misbruik — intimidatie, spam, nepTochten, inhoud met minderjarigen — betekent het einde van het account zonder verdere waarschuwing.",
  "dogPage.bonesForDog": "Doe mee via deze pagina en {dog} krijgt 20 BONES.",
  "dogPage.bonesNote": "BONES zijn de munteenheid van DOGYPT — ze komen op het account van de eigenaar terecht.",
