  "pack.cal.life.rec.tobykeith.exact": "23 jaar 112 dagen",
  "pack.cal.life.rec.pebbles.breed": "Toy Fox Terriër",
  "pack.cal.life.rec.pebbles.country": "VS",
  "pack.cal.life.rec.pebbles.exact": "22 jaar 189 dagen",
  "pack.cal.life.recSince": "sinds {year}",
  "pack.cal.life.tip.weight.title": "Slank blijven is het enige wat bewezen is",
  "pack.cal.life.tip.weight.body": "Van alles wat je voor een hond kunt doen, heeft één ding het hardste bewijs voor levensduur: hem niet laten aankomen. Het verschil tussen een slanke en een licht te zware hond is jaren, geen maanden. Je moet de ribben kunnen voelen zonder te drukken.",
  "pack.cal.life.tip.move.title": "Bewegen op echt terrein, geen rondje om het blok",
  "pack.cal.life.tip.move.body": "Oneffen terrein houdt gewrichten, spieren en geest actief. Elke tocht die je vastlegt, wordt op dit raster een donkere week — en donkere weken zijn het enige wat je echt kunt beïnvloeden.",
  "pack.cal.life.tip.food.title": "Voer dat een hond herkent als voedsel",
  "pack.cal.life.tip.food.body": "Hoe minder stappen er tussen de grondstof en de bak liggen, hoe minder er onderweg mis kan gaan. Brokken zijn geen zonde, maar ook geen dieet — het is een kortere weg.",
  "pack.cal.life.tip.chem.title": "Chemie alleen als het echt nodig is",
  "pack.cal.life.tip.chem.body": "Jaarronde parasietenmiddelen, narcose voor het gemak en antibiotica „voor de zekerheid” zijn beslissingen, geen routine. Vraag jezelf bij elke: wat gebeurt er als ik het niet doe? Waar het antwoord „niets” is, doe het niet.",
  "pack.cal.life.tip.stress.title": "Rust telt net zo zwaar als beweging",
  "pack.cal.life.tip.stress.body": "Een hond die altijd op zijn hoede is, verbrandt zijn lichaam van binnenuit. Ongestoorde slaap, een voorspelbare dag en rust na inspanning zijn geen luiheid — het zijn de uren waarin het lichaam zichzelf herstelt.",
  "pack.cal.life.tip.protocol.title": "Een protocol in plaats van een paniekerige rit naar de dierenarts",
  "pack.cal.life.tip.protocol.body": "Ontworming, coprologie en bloedonderzoek hebben hun eigen vensters in de kalender. Een hond waarvan je twee keer per jaar het bloed laat controleren, wordt niet behandeld — hij blijft zijn klachten voor.",
  "pack.cal.life.tip.joints.title": "Gewrichten worden aangepakt VOORDAT ze pijn gaan doen",
  "pack.cal.life.tip.joints.body": "Jouw hond is nu in de seniorenklasse. De gewrichtenkuur heeft zijn venster in de kalender vanaf november — niet omdat hij mankt, maar zodat hij dat nooit hoeft te doen.",
