  "pack.nature.intro.title": "Wie is jouw hond?",
  "pack.nature.intro.body": "Tweeëntwintig vragen en één checklist. Je leert waaruit jouw hond is opgebouwd, welke taak hij voor je gezin vervult en waarheen zijn balans nu overhelt.",
  "pack.nature.intro.axis1": "Constitutie",
