  "pack.nature.balance.title": "Speelt er nu iets?",
  "pack.nature.balance.body": "De constitutie van jouw hond staat vast voor het leven, maar kan uit balans raken. Vink aan wat van toepassing is — zo veel of zo weinig als je wilt.",
  "pack.nature.balance.none": "Niets op de lijst? Laat het leeg en ga verder — dat is het beste antwoord dat er is.",
  "pack.nature.progress": "Voortgang",
  "pack.nature.special.eyebrow": "Nog vier — we zoeken speciale rollen",
  "pack.nature.special.body": "Deze vier rollen liggen boven de hoofdrol. De meeste honden hebben er geen — dat is normaal.",
  "pack.nature.special.cta": "Resultaat tonen",
  "pack.nature.result.saved": "Opgeslagen op de kaart van jouw hond",
  "pack.nature.result.savedAll": "Opgeslagen op de kaarten van alle honden",
  "pack.nature.ans.yes": "Ja",
  "pack.nature.ans.sometimes": "Soms",
  "pack.nature.ans.no": "Nee",
  "pack.network.ads.body": "Betaalde advertenties zijn een zeer inefficiënte manier om nieuwe hondenliefhebbers te vinden — en een manier om ons geld naar grote bedrijven te gooien. Het werkt veel beter om de leden van de beweging rechtstreeks te belonen voor hun activiteit. Er is één addertje: <strong style=\"font-weight:600\">het werkt alleen echt als jij erop uit gaat en de mensen om je heen over ons vertelt</strong> :)",
  "pack.network.ads.header": "Waarom deze manier?",
  "pack.network.ads.wordAd": "een advertentie",
  "pack.network.ads.wordScroll": "een vreemde scrollt voorbij",
  "pack.network.allBones": "Alle {n}",
  "pack.network.back": "Terug",
  "pack.network.bonesLabel": "Jouw BONES",
  "pack.network.bonesRate": "{n} BONES = 1 €",
  "pack.network.bonesUnit": "bones",
  "pack.network.capHintLog": "Plafond 1:1 — een geschenk kan alleen matchen wat je al hebt geleefd.",
  "pack.network.capHintRow": "Plafond 1:1 — een geschenk matcht wat je hebt geleefd",
  "pack.network.capped.none": "Geen toewijding van deze — je geschenken matchen al alles wat je hebt geleefd. De BONES gaan toch door. <i>Geld verdubbelt de jaren, het vervangt ze nooit.</i>",
  "pack.network.capped.room": "Begrensd op <b style=\"color:#2a1608\">{room}</b> — een geschenk kan alleen matchen wat je hebt geleefd ({lived} toewijding tot nu toe). De BONES gaan toch door; de eer wacht op de dagen.",
  "pack.network.chainFirstInvite": "jouw eerste uitnodiging",
  "pack.network.chainJoined": "{n} toegetreden",
  "pack.network.chainWhoever": "wie ze ook meebrengen",
  "pack.network.chainYou": "jij",
  "pack.network.close": "Sluiten",
  "pack.network.confirmSend": "Weet je het zeker? Eenmaal verzonden, verlaten de BONES jouw saldo — dit kan niet ongedaan worden gemaakt.",
  "pack.network.copyLinkAria": "Uitnodigingslink kopiëren",
  "pack.network.devotionWord": "toewijding",
  "pack.network.emptyLine": "Nog niemand — de eerste naam hier is het begin van jouw lijn.",
  "pack.network.eyebrow": "DOGYPT groeit dankzij jou",
  "pack.network.generatingLink": "Jouw link wordt gegenereerd…",
  "pack.network.linkFailed": "Jouw uitnodigingslink kon niet worden geladen.",
  "pack.network.linkRetry": "Opnieuw proberen",
  "pack.network.groupDirect": "direct",
  "pack.network.groupTheirBrings": "hun uitnodigingen",
  "pack.network.inLine": "In jouw lijn",
  "pack.network.info.bones.body": "BONES is de interne munteenheid van DOGYPT — een speelse naam voor iets echt. Een hond betaalt in botten; wij ook. Je <b>verdient</b> ze door hondenliefhebbers in de roedel te brengen en de beweging voorwaarts te helpen, en je <b>geeft</b> ze uit binnen DOGYPT: steun aan inzamelingsacties voor asielen, merch claimen, en later betalingen aan andere Dogyptiërs voor wat ze maken. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "Wat is BONES?",
  "pack.network.info.why.body": "Een beweging van deze omvang kan niet worden gekocht — geen budget bereikt een vreemde zoals een Dogyptiër een vriend bereikt. Dus legt de roedel de beloning waar het bereik is: bij jou. Als iemand via jouw link toetreedt, krijg jij <b>{l1} BONES</b>; als die iemand meebrengt, krijg jij nog <b>{l2}</b> erbij. Elke Dogyptiër die het woord verspreidt, is geen verkoper — hij is een missionaris, en dat werk eren we.",
  "pack.network.info.why.cap": "Waarom we jou vragen",
  "pack.network.intro": "Een beweging groeit alleen als haar leden de boodschap dragen en nieuwe mensen meebrengen. Daarom vragen we het je rechtstreeks: <strong style=\"color:#2a1608;font-weight:600\">nodig de hondenliefhebbers uit die je kent</strong>. Hier is precies hoe het werkt.",
  "pack.network.inviteLinkHeader": "Jouw uitnodigingslink",
  "pack.network.listSummary": "{n} mensen · {b} BONES verdiend",
  "pack.network.noBonesYetHint": "Nog geen BONES — nodig eerst iemand uit.",
  "pack.network.noOneYet": "nog niemand",
  "pack.network.openWallet": "Portemonnee openen",
  "pack.network.send.grow.lede": "Dit financiert wat de roedel vervolgens bouwt.",
  "pack.network.send.grow.title": "BONES naar de beweging sturen",
  "pack.network.send.help.lede": "Gaat rechtstreeks naar asielen en redding.",
  "pack.network.send.help.title": "BONES naar een hond in nood sturen",
  "pack.network.sendWhere": "Waarheen sturen?",
  "pack.network.shareLink": "Deel jouw link",
  "pack.network.shareText": "Doe mee met de roedel. Word Dogyptiër.",
  "pack.network.showAll": "Bekijk alle {n}",
  "pack.network.soon": "Binnenkort",
  "pack.network.spend.grow.name": "DOGYPT laten groeien",
  "pack.network.spend.grow.sub": "financier de beweging",
  "pack.network.spend.help.name": "Een hond helpen",
  "pack.network.spend.help.sub": "asielen & redding",
  "pack.network.spend.merch.name": "Merch",
  "pack.network.spend.merch.sub": "draag het teken",
  "pack.network.spend.payments.name": "Betalingen",
  "pack.network.spend.payments.sub": "betaal andere Dogyptiërs",
  "pack.network.step1Body": "Stuur hem naar je vrienden die een goed doel zouden steunen. Dat is de hele vraag.",
  "pack.network.step1Title": "Deel jouw link",
  "pack.network.step2Body": "Als iemand via jouw link een <strong style=\"color:#2a1608;font-weight:600\">Heroglyph</strong> maakt, krijg jij <strong style=\"color:#2a1608;font-weight:600\">{l1} BONES</strong>. Als dat lid ook iemand meebrengt, krijgt hij {l1} en <strong style=\"color:#2a1608;font-weight:600\">krijg jij {l2} erbij</strong>.",
  "pack.network.step2Title": "Ze doen mee — jij krijgt BONES",
