  "onepage.apps.claude": "AI van",
  "onepage.apps.dogid.lede": "Elk detail over je hond op één plek — de sleutel tot persoonlijke zorg van je dierenarts en AINUBIS.",
  "onepage.apps.dogtrip.lede": "Ontdek geverifieerde hondvriendelijke routes en log je eigen. Verzamel punten en badges voor jullie actieve leven samen.",
  "onepage.apps.sniffer.lede": "Een hondvriendelijke matchmaker. Vind een maatje, een groep of een partner om de wereld mee te verkennen — als één roedel.",
