  "onepage.apps.cause.lede": "We bouwen DOGYPT samen uit liefde voor honden — 100 % transparant. Elk lid ziet alle inkomsten en uitgaven.",
  "onepage.apps.ainubis.lede": "Onze persoonlijke AI-mentor die je hond door en door kent — met verrijking uit geverifieerde boeken, teksten en korte podcasts.",
