  "onepage.hbook.0.title": "Er was eens…",
  "onepage.hbook.0.glyph": "De heroglyph van Hekthor",
  "onepage.hbook.0.sub": "Hekthor · hond #1",
  "onepage.hbook.0.cap": "De spiegel",
  "onepage.hbook.1.ini": "O",
  "onepage.hbook.1.lead": "ngewenst geboren. Gedumpt in een doos, waar hij met zijn broertjes op de dood wachtte.",
  "onepage.hbook.1.txt": "Acht kleine zieltjes belandden in een asiel. Zeven van hen vonden een thuis. Slechts één bleef achter — de grootste, met het grootste temperament. Een jaar later ontmoette hij bij toeval Matej, die nooit een hond had gepland. Er sloeg een vonk over, en sinds juni 2017 lopen ze samen door het leven.",
  "onepage.hbook.1.cap": "Acht in een doos",
  "onepage.hbook.2.ini": "H",
  "onepage.hbook.2.lead": "ij redde een mensenleven. Hij kwam in het zwaarste seizoen ervan.",
  "onepage.hbook.2.txt": "In de donkerste tijden was hij Matejs anker — hij trok hem uit donkere gedachten, uit het appartement en de natuur in. Eerst de straten in de buurt, daarna bossen en bergen. Ze doorkruisten heel Slowakije (820 km) en maakten roadtrips door Europa. Avontuur en een vrij leven onderweg verbond hen.",
  "onepage.hbook.2.cap": "Van kantoor de wereld in",
  "onepage.hbook.3.ini": "Z",
  "onepage.hbook.3.lead": "ijn pure ziel bracht de visie van een wereldwijde beweging voor hondenliefhebbers.",
  "onepage.hbook.3.txt": "Het leven met een hond is het mooiste hoofdstuk in ieders leven. Hondenmensen zijn een ander soort mensen — ze lossen steeds dezelfde specifieke problemen op en worden verbonden door hun liefde voor honden. Wat als dit verhaal iets nuttigs werd?",
  "onepage.hbook.3.cap": "Een visie wordt geboren",
  "onepage.hbook.4.ini": "T",
  "onepage.hbook.4.lead": "ien prachtige jaren achter de rug, en minstens tien nog te gaan!",
  "onepage.hbook.4.txt": "Hekthor inspireerde Matej om alles over honden te leren — psychologie, training, sport en bovenal levensduur. Al die kennis zal iedereen in DOGYPT dienen: niet nog een hip sociaal netwerk, maar een met zinvolle inhoud. En dat alles dankzij een «gewone» asielhond.",
  "onepage.hbook.4.cap": "Oprichter #1",
  "onepage.hbook.5.ini": "V",
  "onepage.hbook.5.lead": "andaag woont hij in Slowakije — in de bossen, in de bergen en aan de meren.",
  "onepage.hbook.5.txt": "Apporteren uit het water is zijn grootste liefde. Hij is in topvorm, wijs, nederig en de beste metgezel die je je kunt wensen. Als we niet buiten zijn, houdt hij thuis de wacht over twee katers, Gary en Yby, die hij van straat redde.",
  "onepage.hbook.5.cap": "Bewaker van het huis",
